const items=$input.all();
const clean=name=>String(name||'').trim();
const parent=item=>String(item.json.parents?.[0]||'');
const stem=name=>clean(name).toLowerCase().replace(/\.(csv|pdf)$/i,'');
const pdfs=new Map();
for(const item of items){
  const name=clean(item.json.name);
  if(name.toLowerCase().endsWith('.pdf')) pdfs.set(parent(item)+'::'+stem(name),item.json);
}
return items.filter(item=>clean(item.json.name).toLowerCase().endsWith('.csv')).map((item,index)=>{
  const name=clean(item.json.name);
  const pdf=pdfs.get(parent(item)+'::'+stem(name));
  return {json:{
    sourceFileId:String(item.json.id||''),sourceFileName:name,
    sourceFileUrl:String(item.json.webViewLink||('https://drive.google.com/file/d/'+item.json.id+'/view')),
    modifiedTime:String(item.json.modifiedTime||''),
    pdfFileId:pdf?String(pdf.id||''):undefined,pdfFileName:pdf?clean(pdf.name):undefined,
  },pairedItem:{item:index}};
});

const out=[];
for(const [index,item] of $input.all().entries()){
  const buf=await this.helpers.getBinaryDataBuffer(index,'data');
  if(buf.length>10*1024*1024) throw new Error('CSV výpis presahuje 10 MB');
  const text=buf.toString('utf8').replace(/^\uFEFF/,'');
  out.push({json:{
    sourceFileId:String(item.json.sourceFileId||item.json.id||''),
    sourceFileName:String(item.json.sourceFileName||item.binary?.data?.fileName||''),
    sourceFileUrl:String(item.json.sourceFileUrl||''),
    pdfFileId:item.json.pdfFileId?String(item.json.pdfFileId):undefined,
    pdfFileName:item.json.pdfFileName?String(item.json.pdfFileName):undefined,
    csvText:text,
  },pairedItem:{item:index}});
}
return out;
